/// Runs the real `git` binary to build a temp repo fixture. Needed
/// because `GitRepository::discover`/`resolve_commit`/
/// `commits_since_with_pathspec` operate on a real on-disk repo, not a
/// mocked `CommandRunner`.
fn run_git(dir: &Path, args: &[&str]) {
    let status = std::process::Command::new("git")
        .args(args)
        .current_dir(dir)
        .status()
        .expect("git must be installed to run this test");
    assert!(status.success(), "git {args:?} failed in {dir:?}");
}

fn init_repo(root: &Path) {
    run_git(root, &["init", "-q", "-b", "main"]);
    run_git(root, &["config", "user.email", "test@example.com"]);
    run_git(root, &["config", "user.name", "Test"]);
    run_git(root, &["config", "commit.gpgsign", "false"]);
    run_git(root, &["config", "tag.gpgsign", "false"]);
}

/// A tag object with no `tagger` line is what `git fsck` calls
/// `missingTaggerEntry`; GitHub's receive-pack rejects the push carrying it.
