/// Spec: `commits_since_with_pathspec` must only return commits that
/// touched a path under one of the given pathspecs -- mirrors the
/// filtering behavior of `git log -- <pathspecs>`, scoped to simple
/// directory/path-prefix matching.
#[test]
fn test_commits_since_with_pathspec_filters_by_changed_path() {
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();
    init_repo(root);

    std::fs::create_dir_all(root.join("crates/pkg-a")).unwrap();
    std::fs::write(root.join("crates/pkg-a/file.txt"), "a\n").unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "feat: add pkg-a"]);

    std::fs::create_dir_all(root.join("crates/pkg-b")).unwrap();
    std::fs::write(root.join("crates/pkg-b/file.txt"), "b\n").unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "feat: add pkg-b"]);

    std::fs::write(root.join("crates/pkg-a/file.txt"), "a2\n").unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "fix: tweak pkg-a"]);

    let repo = GitRepository::discover(root).unwrap();
    let pathspecs = vec![PathBuf::from("crates/pkg-a")];
    let commits = repo.commits_since_with_pathspec(None, &pathspecs).unwrap();

    let summaries: Vec<&str> = commits.iter().map(|c| c.summary.as_str()).collect();
    assert_eq!(summaries, vec!["fix: tweak pkg-a", "feat: add pkg-a"]);
}

/// Spec: a pathspec of `"."` (the sentinel `changed::package_paths` emits
/// for a manifest that lives at the workspace/package root -- e.g. a
/// single-package repo's `Cargo.toml`) must match every changed path,
/// mirroring real `git log -- .`'s own semantics for the current-
/// directory pathspec. Rust's `Path::starts_with` does NOT treat `.` as
/// a universal prefix (`Path::new("Cargo.toml").starts_with(".")` is
/// `false`), so a naive prefix-match implementation silently matches
/// zero commits for any root-level package -- worse than matching too
/// broadly, since it makes commit-based inference a total no-op for
/// exactly the packages most likely to use it (single-package repos).
#[test]
fn test_commits_since_with_pathspec_root_sentinel_matches_root_level_files() {
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();
    init_repo(root);

    std::fs::write(root.join("Cargo.toml"), "[package]\nname = \"pkg\"\n").unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "chore: add package"]);

    std::fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"pkg\"\ndescription = \"x\"\n",
    )
    .unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", "feat: add a new feature"]);

    let repo = GitRepository::discover(root).unwrap();
    let pathspecs = vec![PathBuf::from(".")];
    let commits = repo.commits_since_with_pathspec(None, &pathspecs).unwrap();

    let summaries: Vec<&str> = commits.iter().map(|c| c.summary.as_str()).collect();
    assert_eq!(
        summaries,
        vec!["feat: add a new feature", "chore: add package"],
        "a \".\" pathspec must match root-level file changes, not zero commits"
    );
}

#[test]
fn test_commits_since_with_pathspec_excludes_unrelated_paths() {

//! Regression test for `commits_since_with_pathspec`'s revwalk bounding.
//! Isolated in its own integration-test binary because
//! `callisto_vcs::revwalk_visit_count` is a process-global counter that
//! other, non-`#[serial]` tests in a shared binary would pollute (see
//! `crates/callisto-graph/tests/apply_persist_open_count_test.rs` for the
//! precedent this file follows).

use std::path::Path;

use callisto_model::CommitSha;
use callisto_vcs::GitRepository;
use serial_test::serial;

fn run_git(dir: &Path, args: &[&str]) {
    let status = std::process::Command::new("git")
        .args(args)
        .current_dir(dir)
        .status()
        .expect("git must be installed to run this test");
    assert!(status.success(), "git {args:?} failed in {dir:?}");
}

fn init_repo(root: &Path) {
    run_git(root, &["init", "-q", "-b", "main"]);
    run_git(root, &["config", "user.email", "test@example.com"]);
    run_git(root, &["config", "user.name", "Test"]);
    run_git(root, &["config", "commit.gpgsign", "false"]);
    run_git(root, &["config", "tag.gpgsign", "false"]);
}

fn commit(root: &Path, n: usize) {
    std::fs::write(root.join("f.txt"), format!("commit {n}\n")).unwrap();
    run_git(root, &["add", "."]);
    run_git(root, &["commit", "-q", "-m", &format!("commit {n}")]);
}

/// Spec: `commits_since_with_pathspec` must bound its walk to `since..HEAD`
/// -- not walk the whole repository history and filter after the fact. 30
/// linear commits precede `since`; 3 more follow it. Under the old
/// two-full-walk-then-exclude implementation, the primary revwalk visits
/// every one of the 33 commits reachable from HEAD regardless of `since`.
/// The bounded implementation must visit only the small number of commits
/// between `since` and HEAD.
#[test]
#[serial]
fn commits_since_with_pathspec_bounds_walk_to_since_head_range() {
    let ws_dir = tempfile::tempdir().unwrap();
    let root = ws_dir.path();
    init_repo(root);

    for n in 1..=30 {
        commit(root, n);
    }

    let since_output = std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .current_dir(root)
        .output()
        .unwrap();
    assert!(since_output.status.success());
    let since_sha = CommitSha::parse(String::from_utf8_lossy(&since_output.stdout).trim()).unwrap();

    for n in 31..=33 {
        commit(root, n);
    }

    let repo = GitRepository::discover(root).unwrap();

    callisto_vcs::reset_revwalk_visit_count();
    let commits = repo.commits_since_with_pathspec(Some(&since_sha), &[]).unwrap();

    assert_eq!(commits.len(), 3, "must return exactly the 3 commits after `since`");

    assert_eq!(
        callisto_vcs::revwalk_visit_count(),
        3,
        "revwalk must visit exactly the 3 commits between `since` and HEAD, not the full 33-commit history"
    );
}

