use crate::revision;
#[cfg(feature = "revision")]
use crate::{Error, Id, Result, bstr::BStr, error::message};

/// Methods for resolving revisions by spec or working with the commit graph.
impl crate::Repository {
    /// Parse a revision specification and turn it into the object(s) it describes, similar to `git rev-parse`.
    ///
    /// # Deviation
    ///
    /// - `@` actually stands for `HEAD`, whereas `git` resolves it to the object pointed to by `HEAD` without making the
    ///   `HEAD` ref available for lookups.
    #[doc(alias = "revparse", alias = "git2")]
    #[cfg(feature = "revision")]
    pub fn rev_parse<'a>(&self, spec: impl Into<&'a BStr>) -> Result<revision::Spec<'_>> {
        revision::Spec::from_bstr(
            spec,
            self,
            revision::spec::parse::Options {
                object_kind_hint: self.config.object_kind_hint,
                ..Default::default()
            },
        )
    }

    /// Parse a revision specification and return single object id as represented by this instance.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    /// # mod doctest { include!(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/doctest.rs")); }
    /// # let repo = doctest::open_repo(doctest::basic_repo_dir()?)?;
    /// let parent = repo.rev_parse_single("HEAD^")?.object()?.into_commit();
    ///
    /// assert_eq!(parent.message_raw()?, "c1\n");
    /// assert_ne!(parent.id, repo.rev_parse_single("HEAD")?);
    /// # Ok(()) }
    /// ```
    #[doc(alias = "revparse_single", alias = "git2")]
    #[cfg(feature = "revision")]
    pub fn rev_parse_single<'repo, 'a>(&'repo self, spec: impl Into<&'a BStr>) -> Result<Id<'repo>> {
        let spec = spec.into();
        self.rev_parse(spec)?.single().ok_or_else(|| {
            let spec: crate::bstr::BString = spec.into();
            Error::from_error(message!("revspec {spec:?} did not resolve to a single object"))
        })
    }

    /// Obtain the best merge-base between commit `one` and `two`, or `None` if there is none.
    /// Graph setup and traversal failures are returned as errors.
    ///
    /// # Performance
    /// For repeated calls, prefer [`merge_base_with_graph()`](Self::merge_base_with_graph()).
    /// Also be sure to [set an object cache](crate::Repository::object_cache_size_if_unset) to accelerate repeated commit lookups.
    #[cfg(feature = "revision")]
    pub fn merge_base(
        &self,
        one: impl Into<gix_hash::ObjectId>,
        two: impl Into<gix_hash::ObjectId>,
    ) -> Result<Option<Id<'_>>> {
        let cache = self.commit_graph_if_enabled()?;
        let mut graph = self.revision_graph(cache.as_ref());
        self.merge_base_with_graph(one, two, &mut graph)
    }

    /// Obtain the best merge-base between commit `one` and `two`, or `None` if there is none, providing a
    /// commit-graph `graph` to potentially greatly accelerate the operation by reusing graphs from previous runs.
    /// Traversal failures are returned as errors.
    ///
    /// # Performance
    /// Be sure to [set an object cache](crate::Repository::object_cache_size_if_unset) to accelerate repeated commit lookups.
    #[cfg(feature = "revision")]
    pub fn merge_base_with_graph(
        &self,
        one: impl Into<gix_hash::ObjectId>,
        two: impl Into<gix_hash::ObjectId>,
        graph: &mut gix_revwalk::Graph<'_, '_, gix_revwalk::graph::Commit<gix_revision::merge_base::Flags>>,
    ) -> Result<Option<Id<'_>>> {
        use crate::prelude::ObjectIdExt;
        let one = one.into();
        let two = two.into();
        let bases = gix_revision::merge_base(one, &[two], graph)?;
        Ok(bases.map(|bases| bases.first().attach(self)))
    }

    /// Get all merge-bases between commit `one` and `others`, or an empty list if there is none, providing a
    /// commit-graph `graph` to potentially greatly speed up the operation.
    /// Traversal failures are returned as errors.
    ///
    /// # Performance
    /// Be sure to [set an object cache](crate::Repository::object_cache_size_if_unset) to speed up repeated commit lookups.
    #[doc(alias = "merge_bases_many", alias = "git2")]
    #[cfg(feature = "revision")]
    pub fn merge_bases_many_with_graph(
        &self,
        one: impl Into<gix_hash::ObjectId>,
        others: &[gix_hash::ObjectId],
        graph: &mut gix_revwalk::Graph<'_, '_, gix_revwalk::graph::Commit<gix_revision::merge_base::Flags>>,
    ) -> Result<Vec<Id<'_>>> {
        use crate::prelude::ObjectIdExt;
        let one = one.into();
        Ok(match gix_revision::merge_base(one, others, graph)? {
            Some(bases) => bases.into_iter().map(|id| id.attach(self)).collect(),
            None => Vec::new(),
        })
    }

    /// Like [`merge_bases_many_with_graph()`](Self::merge_bases_many_with_graph), but without the ability to speed up consecutive calls with a [graph](gix_revwalk::Graph).
    ///
    /// # Performance
    ///
    /// Be sure to [set an object cache](crate::Repository::object_cache_size_if_unset) to speed up repeated commit lookups, and consider
    /// using [`merge_bases_many_with_graph()`](Self::merge_bases_many_with_graph) for consecutive calls.
    #[doc(alias = "git2")]
    #[cfg(feature = "revision")]
    pub fn merge_bases_many(
        &self,
        one: impl Into<gix_hash::ObjectId>,
        others: &[gix_hash::ObjectId],
    ) -> Result<Vec<Id<'_>>> {
        let cache = self.commit_graph_if_enabled()?;
        let mut graph = self.revision_graph(cache.as_ref());
        self.merge_bases_many_with_graph(one, others, &mut graph)
    }

    /// Return the best merge-base among all `commits`, or `None` if `commits` yields no commit or no merge-base was found.
    ///
    /// Use `graph` to speed up repeated calls. Traversal failures are returned as errors.
    #[cfg(feature = "revision")]
    pub fn merge_base_octopus_with_graph(
        &self,
        commits: impl IntoIterator<Item = impl Into<gix_hash::ObjectId>>,
        graph: &mut gix_revwalk::Graph<'_, '_, gix_revwalk::graph::Commit<gix_revision::merge_base::Flags>>,
    ) -> Result<Option<Id<'_>>> {
        use crate::prelude::ObjectIdExt;
        let commit_ids: Vec<_> = commits.into_iter().map(Into::into).collect();
        let Some(first) = commit_ids.first().copied() else {
            return Ok(None);
        };
        let merge_base_id = gix_revision::merge_base::octopus(first, &commit_ids[1..], graph)?;
        Ok(merge_base_id.map(|id| id.attach(self)))
    }

    /// Return the best merge-base among all `commits`, or `None` if `commits` yields no commit or no merge-base was found.
    /// Graph setup and traversal failures are returned as errors.
    ///
    /// For repeated calls, prefer [`Self::merge_base_octopus_with_graph()`] for cache-reuse.
    #[cfg(feature = "revision")]
    pub fn merge_base_octopus(
        &self,
        commits: impl IntoIterator<Item = impl Into<gix_hash::ObjectId>>,
    ) -> Result<Option<Id<'_>>> {
        let cache = self.commit_graph_if_enabled()?;
        let mut graph = self.revision_graph(cache.as_ref());
        self.merge_base_octopus_with_graph(commits, &mut graph)
    }

    /// Create the baseline for a revision walk by initializing it with the `tips` to start iterating on.
    ///

    pub fn lookup(&mut self, id: &gix_hash::oid) -> Result<LazyCommit<'_, 'cache>> {
        self.try_lookup(id)?
            .ok_or_raise(|| gix_error::message!("An object with id {id} could not be found").not_found())
    }
}

fn try_lookup<'graph, 'cache>(
    id: &gix_hash::oid,
    objects: &dyn gix_object::Find,
    cache: Option<&'cache gix_commitgraph::Graph>,
    buf: &'graph mut Vec<u8>,
) -> Result<Option<LazyCommit<'graph, 'cache>>> {
    if let Some(cache) = cache
        && let Some(pos) = cache.lookup(id)
    {
        return Ok(Some(LazyCommit {
            object_hash: id.kind(),
            backing: Either::Right((cache, pos)),
        }));
    }
    Ok(match objects.try_find(id, buf)? {
        Some(data) => data.kind.is_commit().then_some(LazyCommit {
            object_hash: data.object_hash,
            backing: Either::Left(buf),
        }),
        None => None,
    })
}

impl<'a, T> Index<&'a gix_hash::oid> for Graph<'_, '_, T> {
    type Output = T;

    fn index(&self, index: &'a oid) -> &Self::Output {
        &self.map[index]
    }
}

/// A commit that contains all information we can obtain through the commit-graph, which is typically enough to fuel any graph iteration.
pub struct Commit<T> {
    /// The parents of the commit.
    pub parents: SmallVec<[gix_hash::ObjectId; 1]>,
    /// The time at which the commit was created.
    pub commit_time: SecondsSinceUnixEpoch,
    /// The generation of the commit, if available.
    pub generation: Option<u32>,
    /// Any kind of data to associate with this commit.
    pub data: T,
}

impl<T> std::fmt::Debug for Commit<T>
where
    T: std::fmt::Debug,
{
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Commit")
            .field("parents", &self.parents)
            .field("commit_time", &self.commit_time)
            .field("generation", &self.generation)
            .field("data", &self.data)
            .finish()
    }
}

impl<T> Clone for Commit<T>
where
    T: Clone,
{
    fn clone(&self) -> Self {
        Commit {
            parents: self.parents.clone(),
            commit_time: self.commit_time,
            generation: self.generation,
            data: self.data.clone(),
        }
    }
}

/// A commit that provides access to graph-related information, on demand.
///
/// The owned version of this type is called [`Commit`] and can be obtained by calling [`LazyCommit::to_owned()`].
pub struct LazyCommit<'graph, 'cache> {
    object_hash: gix_hash::Kind,
    backing: Either<&'graph [u8], (&'cache gix_commitgraph::Graph, gix_commitgraph::Position)>,
}

enum Either<T, U> {
    Left(T),
    Right(U),
}

use gix_date::SecondsSinceUnixEpoch;
use gix_error::{ErrorExt, Result, message};
use gix_error::{ResultExt, corruption};
use smallvec::SmallVec;

use super::LazyCommit;
use crate::graph::{Commit, Either, Generation};

impl<'graph, 'cache> LazyCommit<'graph, 'cache> {
    /// Return an iterator over the parents of this commit.
    pub fn iter_parents(&self) -> Parents<'graph, 'cache> {
        let backing = match &self.backing {
            Either::Left(buf) => Either::Left(gix_object::CommitRefIter::from_bytes(buf, self.object_hash)),
            Either::Right((cache, pos)) => Either::Right((*cache, cache.commit_at(*pos).iter_parents())),
        };
        Parents { backing }
    }

    /// Returns the timestamp at which this commit was created.
    ///
    /// This is the single-most important date for determining recency of commits.
    /// Note that this can only fail if the commit is backed by the object database *and* parsing fails.
    pub fn committer_timestamp(&self) -> Result<SecondsSinceUnixEpoch> {
        Ok(match &self.backing {
            Either::Left(buf) => gix_object::CommitRefIter::from_bytes(buf, self.object_hash)
                .committer()?
                .seconds(),
            Either::Right((cache, pos)) => cache.commit_at(*pos).committer_timestamp() as SecondsSinceUnixEpoch, // a cast as we cannot represent the error and trying seems overkill
        })
    }

    /// Returns the generation of the commit if it is backed by a commit graph.
    pub fn generation(&self) -> Option<Generation> {
        match &self.backing {
            Either::Left(_) => None,
            Either::Right((cache, pos)) => cache.commit_at(*pos).generation().into(),
        }
    }

    /// Returns the generation of the commit and its commit-time, either from cache if available, or parsed from the object buffer.
    pub fn generation_and_timestamp(&self) -> Result<(Option<Generation>, SecondsSinceUnixEpoch)> {
        Ok(match &self.backing {
            Either::Left(buf) => (
                None,
                gix_object::CommitRefIter::from_bytes(buf, self.object_hash)
                    .committer()?
                    .seconds(),
            ),
            Either::Right((cache, pos)) => {
                let commit = cache.commit_at(*pos);
                (
                    commit.generation().into(),
                    // a cast as we cannot represent the error and trying seems overkill
                    cache.commit_at(*pos).committer_timestamp() as SecondsSinceUnixEpoch,
                )
            }
        })
    }

    /// Convert ourselves into an owned version, which effectively detaches us from the underlying graph.
    /// Use `new_data()` to provide the `data` field for the owned `Commit`.
    pub fn to_owned<T>(&self, new_data: impl FnOnce() -> T) -> Result<Commit<T>> {
        let data = new_data();
        Ok(match &self.backing {
            Either::Left(buf) => {
                use gix_object::commit::ref_iter::Token;
                let iter = gix_object::CommitRefIter::from_bytes(buf, self.object_hash);
                let mut parents = SmallVec::default();
                let mut timestamp = None;
                for token in iter {
                    match token.or_raise(|| corruption("A commit could not be decoded during traversal"))? {
                        Token::Tree { .. } => {}
                        Token::Parent { id } => parents.push(id),
                        Token::Author { .. } => {}
                        Token::Committer { signature } => {
                            timestamp = Some(signature.seconds());
                            break;
                        }
                        _ => {
                            unreachable!(
                                "we break naturally after seeing the committer which is always at the same spot"
                            )
                        }
                    }
                }
                Commit {
                    parents,
                    commit_time: timestamp.unwrap_or_default(),
                    generation: None,
                    data,
                }
            }
            Either::Right((cache, pos)) => {
                let mut parents = SmallVec::default();
                let commit = cache.commit_at(*pos);
                for pos in commit.iter_parents() {
                    let pos =
                        pos.or_raise(|| corruption("Could not find commit position in graph when traversing parents"))?;
                    parents.push(cache.commit_at(pos).id().to_owned());
                }
                let actual = commit.committer_timestamp();
                Commit {
                    parents,
                    commit_time: SecondsSinceUnixEpoch::try_from(actual).or_raise(|| {
                        message!("Commit-graph time could not be presented as signed integer: {actual}").corrupted()
                    })?,
                    generation: Some(commit.generation()),
                    data,
                }
            }
        })
    }
}

/// An iterator over the parents of a commit.
pub struct Parents<'graph, 'cache> {
    backing: Either<
        gix_object::CommitRefIter<'graph>,
        (
            &'cache gix_commitgraph::Graph,
            gix_commitgraph::file::commit::Parents<'cache>,
        ),
    >,
}

impl Iterator for Parents<'_, '_> {
    type Item = Result<gix_hash::ObjectId>;

    fn next(&mut self) -> Option<Self::Item> {
        match &mut self.backing {
            Either::Left(it) => {
                for token in it {
                    match token {
                        Ok(gix_object::commit::ref_iter::Token::Tree { .. }) => continue,
                        Ok(gix_object::commit::ref_iter::Token::Parent { id }) => return Some(Ok(id)),
                        Ok(_unused_token) => break,
                        Err(err) => {
                            return Some(Err(
                                err.and_raise(corruption("An error occurred when parsing commit parents"))
                            ));
                        }
                    }
                }
                None
            }
            Either::Right((cache, it)) => it.next().map(|r| {
                r.map(|pos| cache.id_at(pos).to_owned())
                    .or_raise(|| corruption("An error occurred when parsing parents from the commit graph"))
            }),
        }
    }
}

